(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ht"] = {"ui":{"skip":"Ale nan kontni a","back":"← Tounen sou AI-gile","lang.button":"Lang: {name}","lang.dialog":"Chwazi yon lang","lang.search":"Chèche lang","lang.none":"Pa gen lang ki koresponn","lang.notYet":"{name} poko tradui","theme.aria":"Chanje tèm: klè, fènwa oswa nwa","theme.toLight":"Pase sou tèm klè","theme.toDark":"Pase sou tèm fènwa","theme.toBlack":"Pase sou tèm nwa (nwa toutbon, dous pou ekran OLED)","words.underline":"Souliye mo sa yo sou paj la","words.underlineHelp":"Pase sourit la sou yon mo ki gen pwen anba l, oswa tape l, pou w wè sa l vle di.","index.title":"AI-gile: ekip devlopman AI ou a, sou yon sèl tablo","index.description":"AI-gile se yon tablo kanban pou ekip AI ki kode. Yo travay pandan w ap dòmi; ou jwenn yon ti pil kout ak bagay pou ou deside, teste ak aksepte.","hero.logoAlt":"Ikòn tablo AI-gile","hero.h1.html":"Ekip devlopman AI ou a, sou yon sèl&nbsp;tablo.","hero.alpha":"🐣 Pre-alfa fèmen","hero.alphaTitle":"Li bonè e li poko fini: mèsi paske w ap eseye li!","hero.lede":"Yo bati pandan w ap dòmi. Ou reveye sou yon ti pil kout: kèk kesyon, kèk bagay pou teste, yon dyaman koulè wouj violèt oswa de. Klike, aksepte, retounen bò kafe w la.","dl.windows":"Aplikasyon Windows","dl.browser":"Sèvi ak li nan navigatè w","dl.messenger":"📱 Messenger pou telefòn ou","dl.soon":"Talè konsa","dl.notify":"🔔 Di m lè l ouvè","dl.notifySmall":"Alfa oswa beta","hero.secondary":"Agile, men ekip la pa bezwen kafe stand-up. (Yo fè stand-up kanmenm.)","pitch.h2":"AI-gile an kantite mo ou vle","pitch.lede":"Chwazi yon longè, soti nan yon sèl mo rive 144. Chak longè gen pwòp deskripsyon li, ekri espesyalman pou gwosè sa a. Glise kourseur a oswa sèvi ak flèch yo.","pitch.rangeLabel":"Longè an mo","pitch.dice":"🎲 yon lòt vèsyon","pitch.words.one":"{n} mo","pitch.words.other":"{n} mo","pitch.letters.one":"{n} lèt","pitch.letters.other":"{n} lèt","pitch.chars.one":"{n} karaktè","pitch.chars.other":"{n} karaktè","count.line.html.one":"{n} kat sou tablo a kounye a","count.line.html.other":"{n} kat sou tablo a kounye a","features.aria":"Sa li fè","f.pile.h":"Yon sèl pil pou ou","f.pile.html":"<b>Pou ou</b> gen tout sa k ap tann ou, nan tout pwojè yo: kesyon, bagay pou teste, travay sèlman yon moun ka fè. Lis ou a di ki sa ki vini apre ak konbyen tan sa pran.","f.sleep.h":"Ekip ki travay pandan w ap dòmi","f.sleep.p":"Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou yon kat, ekip la reveye, fè travay la, epi remèt li ba ou ak etap yon moun fatige ka swiv.","f.tester.h":"Yon testè AI tcheke anvan","f.tester.p":"Anvan anyen rive jwenn ou, yon testè swiv etap yo nan yon kopi aplikasyon an epi montre sa l te wè, ak yon foto ekran. Pase sou sa ki pase yo epi aksepte yo ak yon sèl klik.","f.proof.h":"Prèv, pa pwomès","f.proof.p":"Chak remiz montre sa ki chanje: fichye yo, diff la, foto ekran yo. Ou pa bezwen louvri chak aplikasyon pou konnen si li fini.","f.chat.h":"Pale ak chèf ou yo","f.chat.p":"Yon ba sou kote ki sanble ak Discord: yon ikòn pou chak pwojè, dyaman koulè wouj violèt pou sa ki bezwen ou. Voye yon chèf yon lide; li fè kat ak yon plan ladan l, ak yon bouton ✅ Go.","f.tidy.h":"Li ranje tèt li","f.tidy.p":"Kat ki gen rapò fusyone nan yon sèl, tit ki mele korije, epi yon tcheke token kenbe kòd la lejè. Mwens bagay pou w ale vini ant yo, mwens pou w panse.","f.private.h":"Pou ou, sou òdinatè w","f.private.li1":"Tablo a mache sou pwòp machin ou epi li reponn ou sèlman.","f.private.li2":"Mesaj prive ant moun yo chifre de bout an bout.","f.private.li3":"Okenn kont, okenn pisteur, okenn cookie.","f.lang.h":"Nan lang ou","f.lang.p":"Plis pase 120 lang, soti nan Olandè, Galwa ak Japonè rive nan pirat, Yoda ak Klingon, ak yon chanjman rapid pou tounen nan Anglè pou jagon pwofesyonèl la.","f.service.h":"Soti nan yon ide rive nan yon vrè sèvis","f.service.p":"Ou bati yon bagay ak AI moun ap sèvi ak li kounye a? Make l kòm yon sèvis epi tablo a ede w fè l mache byen: verifikasyon uptime, yon paj estati piblik, ensidan ak yon rapò ekri, chanjman ki bezwen yon Ale, sovgad yo tcheke chak jou. Èd montre w chak etap pandan w ap avanse.","msgr.h2":"AI-gile Messenger: ekip ou nan pòch ou","msgr.p1":"Pale ak ekip AI ou san ou pa ouvri tablo a. Chat ak chèf pwojè ou yo ak zanmi ou, epi gade etap tès yon kat e reponn yo, tout sa sou telefòn ou.","msgr.p2":"Pou konekte l, eskane yon kòd QR sou tablo ou. Premye fwa? Yon chat demo byen janti ap fè w vizite.","msgr.when":"Android an premye, apre sa yon vèsyon web pou telefòn ak iPhone.","msgr.who":"Chèf pwojè ou","msgr.b1":"Koreksyon mòd fè nwa a pare. Ou vle etap tès yo?","msgr.b2":"Wi, tanpri!","msgr.b3":"1. Ouvri Paramèt. 2. Chwazi Fè nwa. Èske li sanble byen?","tl.aria":"Liy tan soti nan premye konvèsasyon an rive nan plan an","tl.h2":"Soti nan premye chita pale a rive nan sa k ap vini","tl.lede":"Dat ak lè reyèl, nan pwòp fizo orè ou. Apre jodi a, se plan an, san okenn dat pwomèt.","tl.today":"Jodi a","tl.planned":"planifye","tl.cards.one":"{n} kat","tl.cards.other":"{n} kat","join.h2":"Vin patisipe","join.lede":"Se yon nèg dwòl ki gen bab, AuDHD ak kèk batay ak sante mantal li, ansanm ak anpil ajan pasyan, k ap bati AI-gile. Pou kounye a li prive, nan yon alfa fèmen ak zanmi. Ou ta renmen eseye l lè l ouvè?","join.btn":"Make enterè m","join.small":"N ap ekri ou pa imèl, pa gen lòt bagay","footer.tag":"AI-gile. Okenn pisteur, okenn cookie, okenn kafe stand-up.","footer.licence":"Lisans biznis","footer.status":"Eta","footer.privacy":"Sa nou kenbe","footer.thanks":"Apèl gras a ChilledChat","form.sending":"Ap voye…","form.failed":"Sa pa mache: eseye ankò pita.","form.offline":"Pa t ka rive jwenn AI-gile: eseye ankò pita.","form.keep":"Nou sèvi ak sa sèlman pou n reponn ou, apre sa nou efase l. Okenn pisteur, okenn cookie.","form.keepLink":"Sa nou kenbe","interest.title":"AI-gile: di m lè alfa a ouvè","interest.description":"Kite imèl ou pou konnen kilè alfa oswa beta fèmen AI-gile a ouvè.","interest.h1":"🔔 Di m lè l ouvè","interest.lede":"AI-gile nan pre-alfa fèmen. Kite imèl ou epi n ap ekri ou yon sèl fwa, lè gen yon plas pou ou.","interest.email":"Imèl ou","interest.which":"Ki tès?","interest.alpha":"Alfa fèmen: bonè, brit, anpil chanjman","interest.beta":"Beta: pi estab, pita","interest.both":"Nenpòt, sa ki rive anvan","interest.submit":"Mete m sou lis la","interest.thanks":"Mèsi! Ou sou lis la.","licence.title":"AI-gile: lisans biznis","licence.description":"Ou sèvi ak AI-gile nan biznis ou? Mande yon lisans biznis gratis.","licence.h1":"📜 Lisans biznis","licence.lede":"Ou sèvi ak AI-gile nan travay? Di nou ki moun ou ye ak sa w fè. Si l fè kèk bon, lisans lan gratis.","licence.company":"Konpayi","licence.website":"Sitwèb","licence.what":"Sa w fè","licence.how":"Ki jan sa ede mond lan","licence.email":"Imèl","licence.submit":"Aplike","licence.thanks":"Mèsi! N ap reponn ou pa imèl.","status.title":"Eta AI-gile","status.h1":"Eta AI-gile","status.quiet":"Tout bagay kalm","status.intro":"Èske AI-gile ap mache kounye a? Paj sa a verifye sit entènèt la, pataj tablo, apèl yo ak telechajman an chak 5 minit.","status.up":"Ap mache (li reponn nan {ms} ms)","status.slow":"Li pa t reponn dènye verifikasyon an, n ap eseye ankò","status.down":"An pann: li pa t reponn de dènye verifikasyon yo","status.svc.web":"Sit entènèt","status.svc.web.offers":"Sit sa a: sa AI-gile ye, ak fòm enterè a","status.svc.boards":"Pataj tablo","status.svc.boards.offers":"Tablo piblik, mesaj ant zanmi ak envitasyon","status.svc.calls":"Apèl","status.svc.calls.offers":"Vwa, videyo ak pataj ekran nan AI-gile","status.svc.download":"Telechajman","status.svc.download.offers":"Enstalatè Windows la ak lyen envitasyon yo","status.checking":"Ap verifye…","status.offline":"Pa ka rive jwenn sèvis eta a kounye a (n ap eseye ankò)","status.updated":"mete ajou {ago}","status.justNow":"kounye a menm","status.min":"{n} min de sa","status.hours":"{n} è de sa","status.days":"{n} jou de sa","privacy.title":"AI-gile: sa nou kenbe","privacy.h1":"Sa nou kenbe","privacy.lede":"An kout: sèlman sa ou voye ban nou, epi pa pou lontan.","privacy.only":"Sèlman sa ou voye ban nou: sa ou tape nan yon fòm, tankou imèl ou. Anyen lòt sou ou.","privacy.sealed":"Li sele pou sèvè nou an pa ka li l: nan navigatè w anvan li pati (sou yon navigatè ki pi ansyen, menm moman li rive a). Se sèlman pwòp tablo pa nou ki ka louvri l.","privacy.server":"Li efase sou sèvè a depi li rive sou tablo nou an. Tout sa ki toujou la apre 30 jou efase kanmenm.","privacy.board":"Nou kenbe l sou tablo nou an sèlman jiskaske nou reponn ou, apre sa nou efase l la tou.","privacy.none":"Okenn pisteur, okenn cookie, okenn analitik.","privacy.local":"Lang ou ak chwa limyè oswa fènwa ou rete nan pwòp navigatè w. Yo pa janm voye yo ban nou.","privacy.ask":"Ou vle l disparèt pi vit? Reponn imèl nou an epi di nou sa.","live.h2":"Gade l ap bati, an dirèk","live.caption":"Chak kat kache: ou wè fòm travay la, pa mo yo.","live.watching.one":"an dirèk: {n} ap gade","live.watching.other":"an dirèk: {n} ap gade","live.last.now":"Dènye kat la deplase jis kounye a","live.last.min.one":"Dènye kat la deplase {n} minit de sa","live.last.min.other":"Dènye kat la deplase {n} minit de sa","live.last.hour.one":"Dènye kat la deplase {n} è de sa","live.last.hour.other":"Dènye kat la deplase {n} è de sa","live.last.day.one":"Dènye kat la deplase {n} jou de sa","live.last.day.other":"Dènye kat la deplase {n} jou de sa","live.offline":"Tablo an dirèk la ap pran yon ti repo. Tounen talè.","live.cols":"Backlog|Pou fè|Ap fèt|Ekip la ap verifye|Pou ou test|Pou ekip la|Fini"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robo.","Delege."]},{"n":2,"texts":["Kanban robo.","Ajan, òganize.","Lide, bati."]},{"n":3,"texts":["Kanban pou robo.","Lide vin fonksyon.","Kanban ajan gratis."]},{"n":5,"texts":["Yon tablo kanban ajan jere.","Ou ekri kat. Ajan bati.","Gratis, lokal, teste, tikotan fou."]},{"n":8,"texts":["Yon tablo kanban gratis kote ajan AI travay.","Ekri yon lide. Ajan yo bati l. Ou aksepte.","Agile pou yon moun ak anpil robo pasyan."]},{"n":13,"texts":["Yon tablo kanban sou òdinatè w kote ajan AI pran kat yo pou travay.","Ekri yon lide. Yon ekip ajan bati l. Yon testè verifye l anvan.","Gratis, san kont, san pisteur: yon tablo, kèk robo, epi ou se chèf la."]},{"n":21,"texts":["AI-gile se yon tablo kanban pou travay ak ajan AI ki kode. Yo pran kat yo; se ou menm ki teste yo epi aksepte yo.","Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou nenpòt kat epi ekip la mete men nan travay.","Yon tablo tach pèsonèl, gratis, ki mache sou pwòp òdinatè w. Se robo ki travay. Se ou ki di wi."]},{"n":34,"texts":["Ou mete lide sou yon tablo. Yon ekip ajan AI transfòme yo an fonksyon ki mache, teste yo, epi remèt yo ba ou ak etap pou eseye. Anyen pa konte kòm fini toutotan ou pa di sa.","AI-gile se yon tablo kanban fèt lakay Rich te bati ak anpil èd ajan li jere kounye a yo. Li gratis, li mache sou òdinatè w, epi li pataje ak zanmi, li pa vann.","Imajine yon tablo kanban òdinè, ak kolòn ki soti nan Backlog rive nan Fini, sof ke se ajan AI k ap pran kat yo. Yo rapòte pwogrè, yo poze kesyon lè yo bloke, epi yo toujou tann dwèt chita w anlè."]},{"n":55,"texts":["AI-gile se yon tablo kanban kote ekip la fèt ak ajan AI. Chak pwojè gen yon chèf ki planifye travay la ak èdè ki bati l. Lè yon fonksyon pare, yon testè AI eseye l epi pran yon foto ekran, answit li rive nan pil ou a. Aksepte l, oswa kite yon kòmantè epi yo refè l.","Li te kòmanse kòm yon fason pou yon moun swiv anpil sesyon kodaj AI an menm tan, epi li grandi an yon vrè tablo. Li mache sou machin ou, li pa mande okenn kont, epi li pa gen pisteur. Li gratis pou zanmi ak nenpòt moun ki gen kiryozite. Li poko fini tou, kidonk atann w ak kèk kote ki brit ak kèk sipriz.","Men vèsyon onèt la. Ou toujou dwe gen lide yo, epi ou toujou dwe tcheke rezilta yo. Sa AI-gile fè se tout sa ki nan mitan: li kenbe kat yo nan lòd, li reveye bon ajan an lè w kite yon kòmantè, li montre egzakteman sa ki chanje, epi li mete tout sa nan yon sèl pil kout pou ou."]},{"n":89,"texts":["AI-gile se yon tablo kanban gratis ou fè mache sou pwòp òdinatè w. Olye de moun, chak pwojè gen yon ekip ajan AI: yon chèf ki fè lide ou yo tounen kat ak yon plan, ak èdè ki pran kat yo dapre priyorite. Lè yon bagay bati, yon testè AI swiv etap tès yo epi montre w sa l te wè. Answit li rete tann nan yon sèl pil ki rele Pou ou. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la eseye yon lòt fwa. Anyen pa janm rive nan Fini san ou.","Kèk bagay ou pa t ap atann. Yon gadyen mennen kolòn Pou fè a plen pandan w ap dòmi, li chwazi kat ki pa bezwen repons ou. Yon konteur token montre konbyen ajan yo sèvi jodi a ak semèn sa a, epi Mòd San Token di yo sispann depanse. Ou ka voye mesaj bay zanmi, epi mesaj prive yo chifre de bout an bout. Tablo a pale anviwon 120 lang, ansanm ak Olandè, Flamann, pirat ak Klingon. Pa gen anyen ki koute yon santim, epi pèsonn pa eseye vann ou l.","AI-gile se yon ti pwojè pèsonèl, se pa yon konpayi. Rich te vle okipe plizyè pwojè kodaj AI san l pa louvri chak aplikasyon pou tcheke yo, konsa li menm ak ajan yo bati yon tablo pou sa, answit yo sèvi ak tablo sa a pou bati rès tèt li. Li nan pre-alfa fèmen, sa vle di li mache, plis oswa mwens, pou yon ti pwiyen zanmi. Pa gen paj pri, pa gen bilten, epi pa gen plan kwasans. Si sa sanble itil, ou ka mande pou eseye l lè l ouvè yon ti jan plis."]},{"n":144,"texts":["AI-gile se yon tablo kanban pou yon moun ak anpil ajan AI. Li mache sou pwòp òdinatè w epi li totalman gratis. Ou ajoute pwojè, epi chak pwojè jwenn yon chèf ak yon ti ekip. Ou pale ak chèf la, yon ti jan tankou sou Discord, epi ou dekri yon lide; chèf la fè l tounen kat ak yon plan, answit li tann ou peze Go. Ekip la pase sou kat yo dapre priyorite, ak yon liy kòmand senp ki fèt pou modèl lang. Anvan anyen tounen jwenn ou, yon testè AI swiv etap yo nan yon kopi aplikasyon an epi tache yon foto ekran. Travay ki fini rive nan pil ou a ak fichye ki chanje yo ak diff la. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la reveye pou eseye ankò. Se sèlman ou ki ka mete yon kat nan Fini.","Men apeprè ki jan yon jou ak AI-gile ye. Nan aswè ou kite kèk kòmantè: bouton sa a nan move kote, lis sa a dwe klase, èske nou ta ka gen yon mòd fènwa. Ou ale dòmi. Ajan yo li kòmantè yo, fè chanjman yo, teste yo epi remèt yo ba ou. Si Pou fè a vin vid, gadyen an ranpli l ak kat nan backlog ki pa bezwen repons ou. Nan maten gen yon sèl pil kout: de twa kesyon ak kèk bagay pou eseye, chak ak etap yon moun ki gen dòmi ka swiv ak yon foto ekran ki montre l ap mache. Ou klike sou yo, aksepte bon yo epi voye rès la tounen. Yon konteur token montre sa tout bagay sa a te sèvi, epi Mòd San Token la pou semèn kote ou bezwen ekonomize. Answit ou manje maten, bagay ajan yo poko ka ede ou ak li.","Pou kòmanse, sa AI-gile pa ye. Se pa yon startup, li pa pou vann, epi pèsonn pa ranmase done ou yo. Se yon tablo gratis ki mache sou òdinatè w, san kont, san pisteur epi san cookie. Sa li ye: yon sèl kote ranje pou wè tout pwojè kodaj AI ou yo alafwa, ak yon ekip ajan k ap fè kat yo epi ou menm k ap pran desizyon yo. Li fusyone kat ki gen rapò, li korije tit ki mele, epi li veye pou kòd la rete lejè. Li pale anviwon 120 lang, soti nan Olandè ak Flamann rive nan pirat ak Klingon. Zanmi ka voye mesaj bay youn lòt, an prive epi chifre. Se Rich ak anpil ajan pasyan ki bati l, pi fò tan ap sèvi ak li menm. Li nan pre-alfa fèmen, kidonk li brit kèk kote. Si sa sanble amizan, mande l byen epi petèt w ap antre bonè."]}],"quips":{"1":"Yon sèl mo. Ak kouraj. Petèt twòp kouraj.","3":"Twa mo. Deja pi onèt pase pifò paj pwodwi.","8":"Uit mo. Toujou pi kout pase yon stand-up.","21":"Longè yo se pwen istwa, san dout. Natirèlman.","55":"Senkant-senk mo. De kat fini pandan w t ap li sa.","144":"Sa a se pi long lan. Pa gen 233. Ajan yo ale dòmi."}},"timeline":{"first-idea.name":"Premye lide a","first-idea.line":"Premye konvèsasyon an, anvan menm yon sèl liy kòd te egziste.","first-board.name":"Premye tablo","first-board.line":"Yon tablo ki swiv pwòp konstriksyon li: kat, kolòn, trennen epi depoze, pwojè.","team-roles.name":"Ekip ak wòl","team-roles.line":"Pwofil ajan, modèl ekip, espas ak ki moun ki fè kisa.","install.name":"Enstalasyon ak vèsyon","install.line":"Yon zip yon zanmi ka enstale, mizajou otomatik, kanal ak retounen anndan.","usage-saver.name":"Ekonomi itilizasyon","usage-saver.line":"Mezire sa chak egzekisyon koute, kenbe kòd la lejè, ekonomize limit ou.","friends.name":"Zanmi ak pataj","friends.line":"Mesaj prive, yon relè mele, envitasyon, wòl ak pwojè pataje.","languages.name":"Lang","languages.line":"Chak tèks ekran nan yon fichye lang, ak Olandè ak Flamann an premye.","ai-tester.name":"Testè AI","ai-tester.line":"Yon testè tcheke chak remiz anvan epi montre sa l te wè.","website.name":"Sitwèb la","website.line":"aigile.lol, teaser la ak liy tan sa a.","streaming.name":"Chat ak difizyon an dirèk","streaming.line":"Discord, Twitch, OBS, mòd streamer, GIF ak emoji.","no-ai.name":"Edisyon San AI","no-ai.line":"Yon tablo pou moun ki kode san AI, ak tablo piblik.","night-watch.name":"Gadyen lannwit","night-watch.line":"Yon gadyen ak yon Scrum Master kenbe ekip yo sou travay pandan w ap dòmi.","p-more.name":"Tout rès la","p-more.line":"Ti lide ki toujou ap tann tou pa yo.","p-android.name":"Telefòn ak Android","p-android.line":"Rive jwenn tablo ou a nan yon telefòn, answit yon aplikasyon Android natif.","p-release.name":"Alfa ak apre","p-release.line":"Alfa fèmen, sit la an dirèk, answit beta.","p-languages.name":"Plis lang","p-languages.line":"Plis pase san lang, ak yon mòd imèsyon pou moun k ap aprann.","p-engines.name":"Plis motè AI","p-engines.line":"Chwazi Claude, Codex oswa Gemini pou chak ajan.","p-pro.name":"Pratik pwofesyonèl","p-pro.line":"Etikèt risk, baryè merge, kat ensidan ak ranpa pwoteksyon.","p-self.name":"Pran swen ou","p-self.line":"Mòd fatige, rapèl pou pran swen tèt ou ak 4:20.","p-servers.name":"Sèvè ak kwasans","p-servers.line":"Paramèt sèvè global, wòl ak planifikasyon pou grandi.","p-livestream.name":"Ekstra difizyon","p-livestream.line":"Chat Twitch, emoji pèsonalize ak yon vi dirèk piblik."},"words":{"button":"📖 Jagon pwofesyonèl","h":"📖 Mo eksplike","intro":"Mo ou jwenn nan AI-gile, an mo senp: bati l, chanje l san danje, kenbe l ap mache pou moun k ap sèvi ak li, epi travay an ekip ak AI.","search":"Chèche yon mo…","none":"Pa gen mo ki koresponn.","close":"Fèmen","count":{"one":"{count} mo","other":"{count} mo"},"groups":[{"id":"build","name":"🛠️ Bati l"},{"id":"change","name":"🔀 Chanje l san danje"},{"id":"run","name":"🛎️ Fè yon sèvis mache"},{"id":"team","name":"🤝 Travay an ekip (ak AI tou)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Dosye pwojè a ak kòd li ak tout istwa commits li, souvan kenbe tou sou GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Yon liy travay apa nan kòd la, pou ka fè chanjman san manyen vèsyon prensipal la.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Yon foto sove nan kòd la, ak yon ti nòt sou sa ki chanje. Ou ka toujou tounen nan youn.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Voye foto sove yo (commits) soti sou òdinatè sa a rive sou GitHub, pou yo gen kopi ak pou pataje yo."},{"id":"merge","g":"build","word":"Merge","text":"Mete chanjman yon branch tounen nan vèsyon prensipal la."},{"id":"pr","g":"build","word":"Pull request","text":"Mande pou chanjman yon branch verifye epi fizyone nan vèsyon prensipal la.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ranje kòd la san chanje sa li fè: fichye pi piti, non pi klè, mwens repetisyon."},{"id":"bug","g":"build","word":"Bug","text":"Yon bagay ki pa mache jan li ta dwe.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Eseye yon travay fini pou verifye si li fè sa yo te mande a, avan ou aksepte l.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kout pou quality assurance (garanti kalite): verifikasyon otomatik ki fèt anvan anyen ale an liy. Lè QA wouj, yon bagay pa pase, epi li pa ka ale an liy jiskaske yo ranje sa.","also":["verifikasyon kalite","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Mete yon nouvo vèsyon an liy, pa egzanp sou yon sèvè kote moun yo sèvi ak li."},{"id":"release","g":"change","word":"Vèsyon","text":"Yon pake travay fini ki gen yon non, ki ale an liy ansanm, ak ti nòt sou sa ki chanje. 🚀 Vèsyon ekri nòt yo apati kat ki fini yo.","also":["vèsyon yo","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Retounen sou dènye vèsyon ki te mache a lè yon nouvo vèsyon bay pwoblèm. Nan AI-gile, li fè yon lis etap pou defèt ki te ekri sou chak chanjman.","also":["roll back","retounen dèyè"]},{"id":"live","g":"change","word":"An liy","text":"Vrè vèsyon moun yo sèvi ak li a, pa yon kopi pou fè esè. Devlopè yo rele l production tou.","also":["live","production","pwodiksyon"],"noTip":1},{"id":"change","g":"change","word":"Chanjman","text":"Yon chanjman planifye sou yon bagay moun konte sou li, ekri davans: ki sa, poukisa, risk la, ki lè, ak ki jan pou defèt li. Kòmanse youn ak 🔀 Leve yon chanjman.","also":["chanjman yo","demann chanjman","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Yon bagay ki ka mal pase, ak yon nòt selon ki chans li genyen pou rive ak ki jan li ta grav. ⚠️ Risk kenbe yo nan yon sèl lis, pi gwo nòt la anvan, chak ak yon dat pou gade l ankò.","also":["risk yo","rejis risk","risk register"]},{"id":"chgwin","g":"change","word":"Fenèt chanjman","text":"Moman lè chanjman ka ale an liy, tankou yon mardi swa trankil. Andeyò yon fenèt, yon kat chanjman pa ka fini, sòf si se yon ijans.","also":["fenèt chanjman yo","change window"]},{"id":"gonogo","g":"change","word":"Ale / Pa ale","text":"Yon vòt rapid jis anvan yon chanjman ale an liy: chak moun ki dwe apwouve di Ale oswa Pa ale. Li avanse sèlman lè yo tout dakò.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Apwobasyon","text":"Tann yon wi anvan travay la kòmanse. Yon kat yon zanmi leve, oswa yon chanjman, ap tann nan ✅ Apwobasyon jiskaske ou apwouve l oswa refize l.","also":["apwobasyon yo","approval"]},{"id":"quiettime","g":"change","word":"Moman trankil","text":"Yon peryòd, tankou yon stream, yon demo oswa lannwit, kote anyen pa ale an liy. Ekip yo kontinye travay ak teste, men ale an liy tann jiskaske li fini. Lòt kote yo rele l change freeze.","also":["moman trankil yo","change freeze"]},{"id":"service","g":"run","word":"Sèvis","text":"Yon bagay ou bati moun konte sou li, tankou yon sit entènèt oswa yon app, ke yo okipe pou l kontinye mache. Tcheke “Pwojè sa a se yon sèvis” epi di sa li ofri, ki moun ki sèvi ak li ak ki moun ki sou gad.","also":["sèvis yo","service"]},{"id":"uptime","g":"run","word":"Verifikasyon uptime","text":"Yon verifikasyon otomatik, chak kèk minit, pou wè si sèvis ou a toujou reponn. Si li echwe plizyè fwa youn dèyè lòt, AI-gile ouvè yon kat ensidan pou kont li.","also":["uptime","disponiblite"]},{"id":"statuspage","g":"run","word":"Paj estati","text":"Yon paj piblik ki montre si yon sèvis ap mache (vèt, oranj oswa wouj) ak dènye nouvèl la, pou moun k ap sèvi ak li ka gade olye yo mande.","also":["paj estati yo","status page"]},{"id":"incident","g":"run","word":"Ensidan","text":"Yon bagay ki kase kounye a pou moun k ap sèvi ak li, tankou sit entènèt la ki tonbe. Yon kat 🔥 ensidan pase devan liy lan: fè l mache ankò se premye bagay.","also":["ensidan yo","incident"]},{"id":"major","g":"run","word":"Gwo ensidan","text":"Yon ensidan ki grav anpil: anpil moun touche, oswa lajan oswa done an danje. Yon sèl bouton mete tout ekip yo sou li (swarm), reveye moun ki sou gad la epi mande yon nouvèl estati chak 30 minit.","also":["gwo ensidan yo","major incident"]},{"id":"oncall","g":"run","word":"Sou gad","text":"Se ou ki reponn lè yon bagay kase, menm lannwit. Chak sèvis gen yon manm ekip sou gad yo reveye an premye pou ensidan li yo.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Delè pou reponn","text":"Konbyen tan yon kat ka tann yon premye repons, pa egzanp inèdtan pou yon ensidan. Apre sa li jwenn yon revèy wouj, pou anyen pa bliye an silans. Yo rele l objektif repons tou.","also":["objektif repons","response target"]},{"id":"postmortem","g":"run","word":"Post-mòtèm","text":"Yon ti gade dèyè apre yon ensidan: sa ki te pase, sa ki te ede ak sa pou chanje, san blame pèsonn. Yon ensidan pa ka fèmen san li.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Pwoblèm","text":"Kòz kache dèyè youn oswa plizyè ensidan. Yon kat 🧩 pwoblèm rasanble ensidan ki toujou ap tounen, pou yo jwenn kòz la epi ranje l pou tout tan.","also":["pwoblèm yo","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Kòz rasin","text":"Vrè rezon yon bagay kase, pa sèlman sa ou te wè k ap mal mache. Ranje kòz rasin lan epi ensidan an sispann tounen.","also":["root cause"]},{"id":"workaround","g":"run","word":"Solisyon tanporè","text":"Yon fason pou kenbe bagay yo ap mache jiskaske vrè reparasyon an pare, tankou rekòmanse yon bagay lè li bloke. Yo ekri l sou kat pwoblèm lan pou pèsonn pa oblije chèche l ankò.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Erè ki konnen","text":"Yon pwoblèm yo konprann kòz li epi ki gen yon solisyon tanporè, men yo poko ranje l. 🧩 Erè ki konnen fè lis yo, pou tout moun sèvi ak solisyon tanporè a olye yo fouye ankò.","also":["erè yo konnen","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Enstriksyon etap pa etap pou ranje yon kalite pwoblèm yo konnen, pou yo fè l menm jan, vit, chak fwa. Apre yon gwo ensidan ekip la ka pwopoze ou youn pou ou bay OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Sovgad","text":"Yon kopi done ou te sere pi bonè, pou ou ka retounen sou li si yon bagay pèdi oswa abime. AI-gile fè yon sovgad tablo ou yo chak jou.","also":["sovgad yo","backup","backups"]},{"id":"restore","g":"run","word":"Retabli","text":"Remete done apati yon sovgad. Yon sovgad konte vrèman sèlman lè ou konnen li ka retabli, kidonk li vo lapenn eseye sa de tanzantan.","also":["retabli l","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Lide ak travay ki poko planifye. Anyen la a pa travay jiskaske li deplase nan Pou fè."},{"id":"sprint","g":"team","word":"Sprint","text":"Yon ti peryòd travay (souvan yon semèn oswa de) ak yon kantite kat ki dakò pou fini.","also":["sprints"]},{"id":"standup","g":"team","word":"Reyinyon kout","text":"Yon ti pwen rapid: sa chak manm ekip te fè, sa yo pral fè apre, ak sa k ap bloke yo.","also":["standup","stand-ups","stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Yon tablo ak kolòn (Pou fè, Ap fèt, Fini) kote kat yo deplase de goch a dwat pandan travay la ap fèt."},{"id":"wip","g":"team","word":"Limit WIP","text":"Travay k ap fèt: maksimòm kat yon kolòn ta dwe genyen, pou ekip la fini bagay yo avan l kòmanse plis.","also":["WIP","WIP limit"]},{"id":"dod","g":"team","word":"Definisyon Fini","text":"Ti lis ekip la sou sa “fini” vle di, tankou teste ak eksplike, anvan yo ba ou yon kat. Marasa l, Definisyon Pare, di ki lè yon kat klè ase pou kòmanse.","also":["Definition of Done","Definisyon Pare","Definition of Ready"]},{"id":"testpile","g":"team","word":"Pil tès","text":"Kat ki fini k ap tann ou eseye yo, youn apre lòt. Aksepte youn oswa voye l tounen ak yon nòt, epi pwochen an parèt.","also":["test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Yon gade dèyè sou fason ekip la travay, pou dakò sou yon bagay pou fè pi byen. Nan AI-gile yon retro pwopoze yon chanjman nan fason ekip la travay, epi ou di Go oswa Poko.","also":["retros","retrospektiv","retrospective"]},{"id":"peerreview","g":"team","word":"Revizyon pa yon kolèg","text":"Yon dezyèm pè je: yon lòt AI tcheke travay chak kat anvan li rive jwenn ou, pou mwens erè pase.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Tout moun sou pon an: chak ekip kite lòt travay pou ede sou yon sèl pwojè ijan jiskaske li regle. Lòt pwojè yo tann pandan tan sa a.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Moun ki kenbe travay la ap koule: li wè kat ki bloke, li pouse ekip yo epi li fè ou sonje sa k ap tann. Nan AI-gile, Chèf Scrum Master fè sa nan tout pwojè yo.","also":["Chèf Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ajan","text":"Yon AI ki travay poukont li sou yon travay: li li kòd la, li fè chanjman, li egzekite verifikasyon, epi li rapòte.","also":["agent","agents","ajan"]},{"id":"token","g":"team","word":"Token","text":"Inite yo konte itilizasyon AI ladan l: apeprè kèk lèt tèks ki li oswa ki ekri. Mwens token, plis plan ou rete.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Yon ti kòmand ki mache poukont li nan yon moman presi, egz. lè yon sesyon AI kòmanse, pou ekip la tande kòmantè ou yo.","also":["hooks"]}]}};
